import type { SqlExecutor } from './proxy';

/** The shape of `migrations/migrations.js`, generated by drizzle-kit. */
export type MigrationBundle = {
  journal: { entries: { idx: number; when: number; tag: string }[] };
  migrations: Record<string, string>;
};

const MIGRATIONS_TABLE = '__drizzle_migrations';

/**
 * Applies pending migrations, each in its own transaction. Bookkeeping uses
 * the same table name and `created_at` = journal timestamp as Drizzle's own
 * migrator, so Drizzle tooling reads it the same way.
 *
 * Written by hand because Drizzle's op-sqlite migrator targets an older
 * op-sqlite API (see db/client.ts); this one only needs a `SqlExecutor`.
 */
export const applyMigrations = async (
  run: SqlExecutor,
  bundle: MigrationBundle,
): Promise<number> => {
  await run(
    `CREATE TABLE IF NOT EXISTS ${MIGRATIONS_TABLE} (id INTEGER PRIMARY KEY AUTOINCREMENT, hash TEXT NOT NULL, created_at NUMERIC)`,
    [],
  );
  const last = await run(
    `SELECT created_at FROM ${MIGRATIONS_TABLE} ORDER BY created_at DESC LIMIT 1`,
    [],
  );
  const lastApplied = Number(last[0]?.[0] ?? 0);

  let applied = 0;
  for (const entry of bundle.journal.entries) {
    if (entry.when <= lastApplied) {
      continue;
    }
    const key = `m${String(entry.idx).padStart(4, '0')}`;
    const sqlText = bundle.migrations[key];
    if (!sqlText) {
      throw new Error(`Missing migration ${entry.tag}`);
    }
    const statements = sqlText
      .split('--> statement-breakpoint')
      .map(statement => statement.trim())
      .filter(statement => statement.length > 0);

    await run('BEGIN', []);
    try {
      for (const statement of statements) {
        await run(statement, []);
      }
      await run(
        `INSERT INTO ${MIGRATIONS_TABLE} (hash, created_at) VALUES (?, ?)`,
        [entry.tag, entry.when],
      );
      await run('COMMIT', []);
    } catch (error) {
      await run('ROLLBACK', []).catch(() => undefined);
      throw error;
    }
    applied += 1;
  }
  return applied;
};
